; iff.asm -- chapter 17: LD A,I: the interrupts on or off
; generated by gen17.py
        INCLUDE "msx.inc"
        OUTPUT "iff.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
ticks   EQU RESULTS             ; interrupts taken
; keep writes the border's register with the interrupts off and leaves them as
; it found them; keep2 asks twice. Both are called with the interrupts on and
; off, and then with the frame's signal coming while their LD A,I runs.
init:   di
        ld sp, SYS_AREA
        xor a
        ld (ticks), a
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt
        ld b, LIGHT_GREEN
        call keep               ; 1: the interrupts on
a1:     di
        ld b, BLACK
        call keep               ; 2: off
a2:     ei
        halt
        ld de, 2372
        call wait
        nop
        nop
        nop
        nop
        ld b, LIGHT_GREEN
        call keep               ; 3: on, and the signal comes during LD A,I
a3:     ei
        halt
        ld de, 2372
        call wait
        nop
        nop
        nop
        nop
        ld b, BLACK
        call keep2              ; 4: the same, with keep2
a4:     di
stop:   jr stop

; keep: B into VDP register 7, the border, with the interrupts off; and then
;       the interrupts as they were. Uses A, F.
keep:   ld a, i                 ; P/V: IFF2, the interrupts on or off
        di
k1:     ld a, b
        out (VDP_CTRL), a
        ld a, $87
        out (VDP_CTRL), a
        ret po                  ; they were off: leave them off
        ei
        ret

; keep2: the same, but asks twice when the answer is off
keep2:  ld a, i
        jp pe, k2on             ; on: that answer is sure
k2ask:  ld a, i                 ; off, or an interrupt came just after the first
k2on:   di
        ld a, b
        out (VDP_CTRL), a
        ld a, $87
        out (VDP_CTRL), a
        ret po
        ei
        ret

; isr: counts the interrupts
isr:    push af
        in a, (VDP_CTRL)        ; the status: the VDP takes its signal down
        ld a, (ticks)
        inc a
        ld (ticks), a
        pop af
        ei
        ret

; wait: DE turns of chapter 14's loop, 30 T-states each. Uses A, DE.
wait:   dec de
        ld a, d
        or e
        jr nz, wait
        ret
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
